//! Runs the `miniq` binary on a script of input lines.

use std::io::Write;
use std::process::{Command, Stdio};

use serde_json::Value;

pub struct Output {
    pub responses: Vec<Value>,
    pub raw: String,
    pub status: i32,
}

pub fn run_bytes(input: &[u8]) -> Output {
    let mut child = Command::new(env!("CARGO_BIN_EXE_miniq"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .expect("spawn miniq");
    child.stdin.take().unwrap().write_all(input).unwrap();
    let out = child.wait_with_output().unwrap();
    let raw = String::from_utf8(out.stdout).unwrap();
    let responses = raw.lines().map(|l| serde_json::from_str(l).unwrap()).collect();
    Output { responses, raw, status: out.status.code().unwrap() }
}

pub fn run(lines: &[&str]) -> Output {
    let mut input = lines.join("\n");
    input.push('\n');
    run_bytes(input.as_bytes())
}
