    })
}

/// Parses exactly the canonical spelling `r-<n>` (no sign, no leading zeros).
fn parse_handle(handle: &str) -> Option<u64> {
    let digits = handle.strip_prefix("r-")?;
    if digits.starts_with('0') || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    digits.parse().ok()
}

