#[test]
fn fifo_delivers_one_message_per_group_in_order() {
    let r = run_cmds(vec![
        create("f.fifo", json!({"Fifo": true, "VisibilityTimeout": 10})),
        fifo_send("f.fifo", "a1", "A", "1"),
        fifo_send("f.fifo", "a2", "A", "2"),
        fifo_send("f.fifo", "b1", "B", "3"),
