        create("q", json!({})),
        create("other", json!({})),
        send("q", "a"),
        send("other", "b"),
        receive("q"),    // r-1
        receive("other"), // r-2
        delete("q", "r-9"),
        delete("q", "r-01"),
        delete("q", "R-1"),
        delete("q", "r-1 "),
        delete("q", "r-"),
        delete("q", "r-0"),
        delete("q", "r--1"),
        delete("q", "r-+1"),
        delete("q", "r-99999999999999999999999"),
        delete("q", "garbage"),
        delete("q", "r-2"), // issued for another queue
        delete("ghost", "r-9"),
        json!({"Command": "DeleteMessage", "QueueName": "q"}),
        json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": 1}),
        delete("q", "r-1"),
        delete("q", "r-1"),
        counts("q"),
    ]);
    assert_eq!(
        codes(&r)[6..],
        [
            "ReceiptHandleInvalid", "ReceiptHandleInvalid", "ReceiptHandleInvalid", "ReceiptHandleInvalid",
            "ReceiptHandleInvalid", "ReceiptHandleInvalid", "ReceiptHandleInvalid", "ReceiptHandleInvalid",
            "ReceiptHandleInvalid", "ReceiptHandleInvalid", "ReceiptHandleExpired", "QueueDoesNotExist",
            "MissingParameter", "InvalidParameterValue", "ok", "ReceiptHandleExpired", "ok",
        ]
    );
    assert_eq!(r[22]["Counts"], json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
}

